mapper.select:
SELECT (SUM(tdm51_month_check_cnt) - SUM(tdm51_month_manl_undone_cnt)) / SUM(tdm51_month_check_cnt) * 100.0 AS prog_rate , SUM(tdm51_month_check1_cnt) / SUM(tdm51_month_check_cnt) * 100 AS suff_rate , SUM(tdm51_month_check_cnt) || ' / ' || '<'||'b style=color:#0171C0;'||'>'||SUM(COALESCE(tdm51_month_check1_cnt,0))||'<'||'/b'||'>' || ' / ' || '<'||'b style=color:#DD5E5E;'||'>'||SUM(COALESCE(tdm51_month_check2_cnt,0))||'<'||'/b'||'>' || ' / ' || SUM(COALESCE(tdm51_month_check9_cnt,0)) AS check_cnt_info FROM ( SELECT t.* FROM ( SELECT org00_kor_nm AS tdm51_org_nm , COUNT(*) AS tdm51_month_check_cnt /*당월점검_대상*/ , CASE WHEN #{statusType} = '1' THEN SUM(CASE WHEN tdm52_check_status_cd = '25' THEN 0 ELSE 1 END) ELSE SUM(CASE WHEN tdm52_check_status_cd >= '19' AND tdm52_check_status_cd != '26' THEN 0 ELSE 1 END) END AS tdm51_month_manl_undone_cnt /*당월점검_미점검*/ , CASE WHEN #{statusType} = '1' THEN SUM(CASE WHEN tdm52_check_status_cd = '25' AND tdm52_check_result_cd = '1' THEN 1 ELSE 0 END) ELSE SUM(CASE WHEN tdm52_check_status_cd >= '19' AND tdm52_check_status_cd != '26' AND tdm52_check_result_cd = '1' THEN 1 ELSE 0 END) END AS tdm51_month_check1_cnt /*당월점검_적정*/ , CASE WHEN #{statusType} = '1' THEN SUM(CASE WHEN tdm52_check_status_cd = '25' AND tdm52_check_result_cd = '2' THEN 1 ELSE 0 END) ELSE SUM(CASE WHEN tdm52_check_status_cd >= '19' AND tdm52_check_status_cd != '26' AND tdm52_check_result_cd = '2' THEN 1 ELSE 0 END) END AS tdm51_month_check2_cnt /*당월점검_미흡*/ , CASE WHEN #{statusType} = '1' THEN SUM(CASE WHEN tdm52_check_status_cd = '25' AND tdm52_check_result_cd = '9' THEN 1 ELSE 0 END) ELSE SUM(CASE WHEN tdm52_check_status_cd >= '19' AND tdm52_check_status_cd != '26' AND tdm52_check_result_cd = '9' THEN 1 ELSE 0 END) END AS tdm51_month_check9_cnt /*당월점검_해당없음*/ , org00_sort_order AS org_sort_order FROM tdm50_chck_job INNER JOIN tdm51_chck_org ON tdm51_chck_job_id = tdm50_chck_job_id INNER JOIN getOrg(#{companyId}, CAST(#{stdDate} AS DATE)) ON org00_org_id = tdm51_org_id INNER JOIN tdm52_chck_manl ON tdm52_chck_org_id = tdm51_chck_org_id WHERE tdm50_company_id = #{companyId} AND tdm50_check_ym = #{checkYm}
AND tdm51_exct_id = #{exctId}
AND tdm51_org_id = f_get_tdmOrg_id2(#{companyId}, #{orgId}, tdm50_start_date)
GROUP BY org00_kor_nm, org00_sort_order ) t ) tt

SELECT ROW_NUMBER() OVER(ORDER BY tdm51_exct_nm COLLATE "ko_KR.utf8", tdm51_role_nm COLLATE "ko_KR.utf8") AS chck_org_id , tdm51_exct_nm AS exct_name , tdm51_role_nm AS role_name , CAST(NULL AS VARCHAR) AS org_name , tdm51_month_check_cnt AS month_check_cnt , tdm51_month_manl_undone_cnt AS month_manl_undone_cnt , tdm51_month_check1_cnt AS month_check1_cnt , tdm51_month_check2_cnt AS month_check2_cnt , tdm51_month_check9_cnt AS month_check9_cnt , CASE WHEN tdm51_month_check_cnt = 0 THEN 0 ELSE (tdm51_month_check_cnt - tdm51_month_manl_undone_cnt) / tdm51_month_check_cnt * 100.0 END AS prog_rate FROM ( SELECT emp00_kor_nm AS tdm51_exct_nm , tdm20_role_nm AS tdm51_role_nm , SUM(CASE WHEN tdm52_chck_manl_id IS NOT NULL THEN 1 ELSE 0 END) AS tdm51_month_check_cnt /*당월점검_대상*/ , SUM(CASE WHEN tdm52_chck_manl_id IS NULL THEN 0 ELSE (CASE WHEN #{statusType} = '1' THEN (CASE WHEN tdm52_check_status_cd = '25' THEN 0 ELSE 1 END) ELSE (CASE WHEN tdm52_check_status_cd >= '19' AND tdm52_check_status_cd != '26' THEN 0 ELSE 1 END) END) END) AS tdm51_month_manl_undone_cnt /*당월점검_미점검*/ , SUM(CASE WHEN #{statusType} = '1' THEN (CASE WHEN tdm52_check_status_cd = '25' AND tdm52_check_result_cd = '1' THEN 1 ELSE 0 END) ELSE (CASE WHEN tdm52_check_status_cd >= '19' AND tdm52_check_status_cd != '26' AND tdm52_check_result_cd = '1' THEN 1 ELSE 0 END) END) AS tdm51_month_check1_cnt /*당월점검_적정*/ , SUM(CASE WHEN #{statusType} = '1' THEN (CASE WHEN tdm52_check_status_cd = '25' AND tdm52_check_result_cd = '2' THEN 1 ELSE 0 END) ELSE (CASE WHEN tdm52_check_status_cd >= '19' AND tdm52_check_status_cd != '26' AND tdm52_check_result_cd = '2' THEN 1 ELSE 0 END) END) AS tdm51_month_check2_cnt /*당월점검_미흡*/ , SUM(CASE WHEN #{statusType} = '1' THEN (CASE WHEN tdm52_check_status_cd = '25' AND tdm52_check_result_cd = '9' THEN 1 ELSE 0 END) ELSE (CASE WHEN tdm52_check_status_cd >= '19' AND tdm52_check_status_cd != '26' AND tdm52_check_result_cd = '9' THEN 1 ELSE 0 END) END) AS tdm51_month_check9_cnt /*당월점검_해당없음*/ FROM tdm50_chck_job INNER JOIN tdm51_chck_org ON tdm51_chck_job_id = tdm50_chck_job_id LEFT JOIN tdm52_chck_manl ON tdm52_chck_org_id = tdm51_chck_org_id INNER JOIN tdm20_role ON tdm20_role_id = tdm51_role_id INNER JOIN getPerson(#{companyId}, tdm50_start_date) ON emp00_person_id = tdm51_exct_id WHERE tdm50_company_id = #{companyId} AND tdm50_check_ym = #{checkYm}
AND tdm51_exct_id = #{exctId}
GROUP BY emp00_kor_nm, tdm20_role_nm ) t

SELECT ROW_NUMBER() OVER(ORDER BY org_sort_order) AS chck_org_id , CAST(NULL AS VARCHAR) AS exct_name , CAST(NULL AS VARCHAR) AS role_name , tdm51_org_nm AS org_name , tdm51_month_check_cnt AS month_check_cnt , tdm51_month_manl_undone_cnt AS month_manl_undone_cnt , tdm51_month_check1_cnt AS month_check1_cnt , tdm51_month_check2_cnt AS month_check2_cnt , tdm51_month_check9_cnt AS month_check9_cnt , (tdm51_month_check_cnt - tdm51_month_manl_undone_cnt) / tdm51_month_check_cnt * 100.0 AS prog_rate FROM ( SELECT org00_kor_nm AS tdm51_org_nm , COUNT(*) AS tdm51_month_check_cnt /*당월점검_대상*/ , CASE WHEN #{statusType} = '1' THEN SUM(CASE WHEN tdm52_check_status_cd = '25' THEN 0 ELSE 1 END) ELSE SUM(CASE WHEN tdm52_check_status_cd >= '19' AND tdm52_check_status_cd != '26' THEN 0 ELSE 1 END) END AS tdm51_month_manl_undone_cnt /*당월점검_미점검*/ , CASE WHEN #{statusType} = '1' THEN SUM(CASE WHEN tdm52_check_status_cd = '25' AND tdm52_check_result_cd = '1' THEN 1 ELSE 0 END) ELSE SUM(CASE WHEN tdm52_check_status_cd >= '19' AND tdm52_check_status_cd != '26' AND tdm52_check_result_cd = '1' THEN 1 ELSE 0 END) END AS tdm51_month_check1_cnt /*당월점검_적정*/ , CASE WHEN #{statusType} = '1' THEN SUM(CASE WHEN tdm52_check_status_cd = '25' AND tdm52_check_result_cd = '2' THEN 1 ELSE 0 END) ELSE SUM(CASE WHEN tdm52_check_status_cd >= '19' AND tdm52_check_status_cd != '26' AND tdm52_check_result_cd = '2' THEN 1 ELSE 0 END) END AS tdm51_month_check2_cnt /*당월점검_미흡*/ , CASE WHEN #{statusType} = '1' THEN SUM(CASE WHEN tdm52_check_status_cd = '25' AND tdm52_check_result_cd = '9' THEN 1 ELSE 0 END) ELSE SUM(CASE WHEN tdm52_check_status_cd >= '19' AND tdm52_check_status_cd != '26' AND tdm52_check_result_cd = '9' THEN 1 ELSE 0 END) END AS tdm51_month_check9_cnt /*당월점검_해당없음*/ , org00_sort_order AS org_sort_order FROM tdm50_chck_job INNER JOIN tdm51_chck_org ON tdm51_chck_job_id = tdm50_chck_job_id INNER JOIN getOrg(#{companyId}, tdm50_start_date) ON org00_org_id = tdm51_org_id INNER JOIN tdm52_chck_manl ON tdm52_chck_org_id = tdm51_chck_org_id WHERE tdm50_company_id = #{companyId} AND tdm50_check_ym = #{checkYm}
AND tdm51_exct_id = #{exctId}
GROUP BY org00_kor_nm, org00_sort_order ) t

SELECT tdm52_chck_manl_id AS chck_manl_id , org00_kor_nm AS org_name /*점검부서*/ , emp00_kor_nm AS checker_name /*점검자*/ , CONCAT('('||tdm43_manl_cd||') ', tdm43_check_item) AS check_item , f_cdnm('CycleCode', tdm43_check_cycle_cd, tdm43_company_id, f_today()) AS check_cycle_name /*점검주기*/ , f_cdnm('TdmCheckStatus', tdm52_check_status_cd, tdm51_company_id, f_today()) AS check_status_name /*진행상태*/ FROM tdm50_chck_job INNER JOIN tdm51_chck_org ON ( tdm51_company_id = tdm50_company_id AND tdm51_check_ym = tdm50_check_ym ) INNER JOIN tdm52_chck_manl ON tdm52_chck_org_id = tdm51_chck_org_id INNER JOIN tdm43_manl ON tdm43_manl_id = tdm52_manl_id INNER JOIN getOrg(#{companyId}, tdm50_start_date) ON org00_org_id = tdm51_org_id INNER JOIN getPerson(#{companyId}, tdm50_start_date) ON emp00_person_id = tdm52_checker_id WHERE tdm50_company_id = #{companyId} AND tdm50_check_ym = #{checkYm}
AND tdm51_exct_id = #{exctId}
AND COALESCE(tdm52_check_status_cd,'10') != '25' /*(25:승인완료)*/
AND COALESCE(tdm52_check_status_cd,'10') < '19' /*(19:점검완료)*/ AND COALESCE(tdm52_check_status_cd,'10') != '26' /*(26:승인반려)*/
AND tdm51_org_id = f_get_tdmOrg_id2(#{companyId}, #{orgId}, tdm50_start_date) AND 'Y' = CASE WHEN #{retrieveType} = '1' AND COALESCE(tdm52_check_status_cd,'10') < '19' THEN 'Y' /*조회구분(1:미점검)*/ WHEN #{retrieveType} = '2' AND COALESCE(tdm52_check_status_cd,'10') = '26' THEN 'Y' /*조회구분(2:반려)*/ WHEN #{retrieveType} = '3' AND COALESCE(tdm52_check_result_cd,'0' ) = '2' THEN 'Y' /*조회구분(3:당월발생미흡)*/ ELSE 'N' END
ORDER BY org00_kor_nm COLLATE "ko_KR.utf8" , tdm43_task_nm COLLATE "ko_KR.utf8" , tdm43_task_relate_detail_nm COLLATE "ko_KR.utf8" , tdm43_task_relate_duty_nm COLLATE "ko_KR.utf8" , tdm43_manl_cd

SELECT COUNT(*)
  FROM tdm08_manager_info
 WHERE tdm08_company_id   = #{companyId}
   AND tdm08_person_id    = #{personId}
   AND tdm08_manager_type IN ('10','11')    /*(10:회사책무관리자 / 11:회사책무담당자)*/
   AND CAST(#{stdDate} AS DATE) BETWEEN tdm08_start_date AND COALESCE(tdm08_end_date,'2999-12-31'::date)
